<?php $reviewOrders=all("SELECT o.id,o.reference,o.product_name,u.email FROM shop_orders o JOIN customers u ON u.id=o.customer_id JOIN shop_contracts c ON c.order_id=o.id WHERE c.state NOT IN ('ended','unpaid_cancelled') ORDER BY (o.customer_id=?) DESC,o.id DESC",[(int)$request['customer_id']]); ?>
<section class="panel form-panel contract-review" id="kuendigung-<?= (int)$request['id'] ?>">
<h2>Kündigung prüfen · <?= e($request['reference']) ?></h2><p><?= e($request['name'].' · '.$request['email']) ?></p>
<dl class="detail-list"><div><dt>Genannter Vertrag</dt><dd><?= e($request['contract_reference']) ?></dd></div><div><dt>Eingang</dt><dd><?= admin_contract_timestamp($request['received_ts']) ?></dd></div><div><dt>Art</dt><dd><?= $request['kind']==='extraordinary'?'Außerordentliche Kündigung':'Ordentliche Kündigung' ?></dd></div><div><dt>Gewünschtes Ende</dt><dd><?= e($request['requested_date']?:'frühestmöglich') ?></dd></div></dl>
<?php if($request['reason']): ?><p class="pre-wrap"><?= e($request['reason']) ?></p><?php endif ?>
<form method="post"><?= csrf() ?><input type="hidden" name="action" value="contract_cancel_approve"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>">
<label class="field"><span>Vertrag zuordnen</span><select name="order_id" required><option value="">Vertrag wählen</option><?php foreach($reviewOrders as $candidate): ?><option value="<?= (int)$candidate['id'] ?>" <?= (int)$request['order_id']===(int)$candidate['id']?'selected':'' ?>><?= e($candidate['reference'].' · '.$candidate['email'].' · '.$candidate['product_name']) ?></option><?php endforeach ?></select></label>
<label class="field"><span>Bestätigtes Vertragsende</span><input type="date" name="effective_date" required min="<?= date('Y-m-d',(int)$request['received_ts']) ?>"></label><label class="checkbox-field"><input type="checkbox" name="identity_verified" required><span>Identität, Vertragszuordnung und Kündigungsgrund geprüft.</span></label><button class="button button-teal">Kündigung übernehmen & bestätigen</button></form>
<?php if(!$request['order_id'] || !contract_for_order((int)$request['order_id'])): ?><details class="order-admin-operation"><summary>Bestandsvertrag persönlich bearbeitet</summary><p>Identität prüfen und die tatsächliche Beendigung von Vertrag, Abrechnung und Anbieterleistung dokumentieren.</p><form method="post"><?= csrf() ?><input type="hidden" name="action" value="contract_cancel_manual"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><label class="field"><span>Tatsächlicher Beendigungszeitpunkt</span><input type="datetime-local" name="effective_datetime" required max="<?= date('Y-m-d\TH:i') ?>"></label><label class="checkbox-field"><input type="checkbox" name="manual_confirmed" required><span>Identität geprüft; Vertrag, Abrechnung und Anbieterleistung tatsächlich beendet.</span></label><button class="button button-outline">Abschluss dokumentieren & bestätigen</button></form></details><?php endif ?>
</section>
